import io,gzip,base64,zipfile
import pandas as pd, numpy as np, streamlit as st

st.set_page_config(page_title="V6.11 Mikro Veto WF",page_icon="🧪",layout="wide")
st.title("🧪 V6.11 — MİKRO-GEOMETRİ VETO / KRONOLOJİK TEST")
st.success("ZERO-UPLOAD — V6.10 verisi gömülü.")
DATA=""""""

@st.cache_data
def load():
    return pd.read_csv(io.BytesIO(gzip.decompress(base64.b64decode(DATA))))

d=load().sort_values("draw_no").reset_index(drop=True)

# Candidate signal is derived only from PRE-H micro geometry.
# No threshold is optimized on the test block itself.
def candidate(r):
    return (r["pre_member_delta"]<=0) and (r["T21_mean_abs_drift"]<=0.50)

# expanding-window audit: candidate definition fixed before each tested row
d["micro_veto"]=d.apply(candidate,axis=1)
d["kept"]=~d.micro_veto
base_acc=d.correct.mean()
kept=d[d.kept]
veto=d[d.micro_veto]

c1,c2,c3,c4=st.columns(4)
c1.metric("Base",f"{base_acc*100:.2f}%")
c2.metric("Veto olay",len(veto))
c3.metric("Veto içi yanlış",int((veto.correct==0).sum()))
c4.metric("Veto sonrası",f"{kept.correct.mean()*100:.2f}%" if len(kept) else "—")

# chronological thirds, no tuning
n=len(d)
d["chrono_part"]=pd.cut(np.arange(n),[-1,n//3,2*n//3,n],labels=["ERKEN","ORTA","SON"])
audit=(d.groupby("chrono_part",observed=True).apply(
    lambda g: pd.Series({
      "events":len(g),"base_correct":int(g.correct.sum()),"base_acc":g.correct.mean(),
      "veto_events":int(g.micro_veto.sum()),
      "veto_wrong":int(((g.micro_veto)&(g.correct==0)).sum()),
      "kept_events":int((~g.micro_veto).sum()),
      "kept_correct":int(g.loc[~g.micro_veto,"correct"].sum()),
      "kept_acc":g.loc[~g.micro_veto,"correct"].mean() if (~g.micro_veto).any() else np.nan
    }),include_groups=False).reset_index())

st.subheader("Kronolojik üç parça")
st.dataframe(audit,use_container_width=True,hide_index=True)

st.subheader("Veto edilen olaylar")
st.dataframe(veto[["draw_no","date","time","correct","pre_member_delta","T21_mean_abs_drift",
                  "expert_character","actual_motion"]],use_container_width=True,hide_index=True)

st.warning("Bu test yalnız aday mikro-vetonun mevcut 161 olay içindeki kronolojik davranışını ölçer. Aynı 161 olaydan keşfedildiği için başarı artışı bağımsız gelecek doğrulaması sayılmaz.")

bio=io.BytesIO()
with zipfile.ZipFile(bio,"w",zipfile.ZIP_DEFLATED) as z:
    z.writestr("00_MANIFEST.txt","V6.11 MIKRO VETO KRONOLOJIK AUDIT\nAday: pre_member_delta<=0 AND T21_mean_abs_drift<=0.50\nTest blogunda esik optimizasyonu yok.\n")
    z.writestr("01_ALL_EVENTS_WITH_VETO.csv",d.to_csv(index=False).encode("utf-8-sig"))
    z.writestr("02_VETO_EVENTS.csv",veto.to_csv(index=False).encode("utf-8-sig"))
    z.writestr("03_CHRONO_AUDIT.csv",audit.to_csv(index=False).encode("utf-8-sig"))
st.download_button("⬇️ V6.11 TEK ZIP",bio.getvalue(),"HIZLI_ON_V6_11_MIKRO_VETO_WF.zip","application/zip",use_container_width=True)
